shell.baseCss:
*{box-sizing:border-box}
html{color-scheme:dark light;scroll-behavior:smooth}
body{background:#0b0b0b;color:#8a8a8a;font:14px/1.55 -apple-system,system-ui,sans-serif;
 margin:0;padding:22px 20px 90px;max-width:1080px}
h1{color:#e6e6e6;font-size:19px;font-weight:600;margin:0 0 4px}
.sub{color:#8a8a8a;margin:0 0 16px;font-size:13px;max-width:78ch}
h2{color:#d0d0d0;font-size:11px;font-weight:600;margin:32px 0 9px;
 text-transform:uppercase;letter-spacing:.09em}
.skip{position:absolute;left:12px;top:-80px;background:#e6e6e6;color:#111;padding:8px 11px;
 border-radius:4px;z-index:20}.skip:focus{top:12px}
.revision{color:#b8b8b8;font-size:12px;margin:0 0 12px}.revision strong{color:#e6e6e6}
.contents{border:1px solid #262626;border-radius:5px;margin:12px 0 18px;padding:9px 12px;max-width:100%}
.contents summary{color:#d0d0d0;cursor:pointer;font-size:12px;font-weight:600}
.contents .preface-link{display:block;color:#9cbfd8;margin:9px 0 2px}
.contents ol{columns:3;column-gap:26px;margin:10px 0 2px;padding-left:20px}
.contents li{break-inside:avoid;margin:2px 0}.contents a{color:#9cbfd8;text-decoration:none}
.contents a:hover,.contents a:focus{text-decoration:underline}
.bar{position:sticky;top:0;background:#0b0b0b;padding:10px 0 12px;margin-bottom:6px;
 border-bottom:1px solid #1e1e1e;z-index:9;display:flex;gap:6px;flex-wrap:wrap}
.sw{font:11px/1 system-ui,sans-serif;padding:7px 11px;border-radius:4px;border:1px solid;
 cursor:pointer;opacity:.68;transition:opacity .12s}
.sw:hover{opacity:.8} .sw.on{opacity:1;box-shadow:0 0 0 1px currentColor}
.motion-toggle{background:transparent;color:inherit;border-color:currentColor}
.motion-toggle:disabled{cursor:not-allowed;opacity:.75}
.sw:focus-visible,.term:focus-visible,.contents summary:focus-visible{outline:2px solid #8bb8ff;outline-offset:2px}
.term{border:1px solid;border-radius:5px;padding:13px 15px;margin:0;overflow-x:auto;
 font:12.5px/1.45 "SF Mono",Menlo,Consolas,"DejaVu Sans Mono",monospace;
 white-space:pre;font-variant-ligatures:none}
.bar2{display:flex;gap:16px;margin-top:8px;align-items:center}
.bar2 label{font-size:11px;color:#909090;display:flex;gap:6px;align-items:center}
.bar2 input[type=range]{width:180px}
.bold{font-weight:700} .ital{font-style:italic} .ul{text-decoration:underline}
.uldot{text-decoration:underline dotted;text-underline-offset:2px}
.focus-indicator{box-shadow:inset 0 -2px 0 currentColor}
.sr-only{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;
 overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}
body[data-preview-motion="off"] *,body[data-preview-motion="off"] *::before,
body[data-preview-motion="off"] *::after{animation:none!important;transition:none!important}
.gap{display:block;height:1.45em}
.bdot{animation:bd 1.1s steps(1,end) infinite}
@keyframes bd{0%,55%{opacity:1}56%,100%{opacity:.2}}
.cur-blink{animation:cb 1.06s steps(1,end) infinite}
@keyframes cb{0%,50%{opacity:1}51%,100%{opacity:0}}
.sp{display:inline-block;inline-size:1ch;text-align:center}
.rmp span{display:inline-block;white-space:pre}
.rmp-shimmer span{animation:shm 1.8s linear infinite;animation-delay:calc(var(--i)*60ms - 10800ms)}
@keyframes shm{0%,88%{color:inherit}92%{color:var(--hi);filter:brightness(1.7)}96%,100%{color:inherit}}
.rmp-wave span{animation:wav 2.4s ease-in-out infinite;animation-delay:calc(var(--i)*70ms - 14400ms)}
@keyframes wav{0%,100%{opacity:.55}50%{opacity:1;filter:brightness(1.4)}}
.rmp-breathe span{animation:brt 2.6s ease-in-out infinite}
@keyframes brt{0%,100%{opacity:.45}50%{opacity:1}}
.rmp-pulse span{animation:pls 1s steps(1,end) infinite}
@keyframes pls{0%,50%{opacity:1}51%,100%{opacity:.35}}

@media (prefers-reduced-motion:reduce){
 html{scroll-behavior:auto}
 *,*::before,*::after{animation:none!important;transition:none!important}
}
@media (max-width:760px){
 body{padding-inline:12px}.contents ol{columns:1}.term{padding:11px 12px}.bar{position:static}
}


.rmp-sweepbar span{animation:swb 1.6s linear infinite;animation-delay:calc(var(--i)*-70ms)}
.rmp-sweepbar-once.once-ready span{animation:swb 1.6s linear 1 both;animation-delay:calc(var(--i)*70ms)}
@keyframes swb{0%,80%{opacity:.55}88%{opacity:1;filter:brightness(1.9)}96%,100%{opacity:.55}}

.rmp-glint span{animation:gln 6s linear infinite;animation-delay:calc(var(--i)*-32ms)}
@keyframes gln{0%,95%{color:inherit}96.5%{color:var(--hi);filter:brightness(2)}98%,100%{color:inherit}}
.rmp-tide span{animation:tid 4.6s ease-in-out infinite;animation-delay:calc(var(--i)*-52ms)}
@keyframes tid{0%,100%{opacity:.42}50%{opacity:1;filter:brightness(1.3)}}
.rmp-flicker span{animation:flk 2.7s steps(1,end) infinite;animation-delay:calc(mod(var(--i)*11,7)*-91ms)}
@keyframes flk{0%,41%{opacity:1}42%,44%{opacity:.45}45%,71%{opacity:1}72%,73%{opacity:.6}74%,100%{opacity:1}}
.rmp-twinkle span{animation:twk 3.3s steps(1,end) infinite;animation-delay:calc(mod(var(--i)*13,19)*-174ms)}
@keyframes twk{0%,6%{opacity:1;filter:brightness(1.9)}7%,100%{opacity:.55}}
.rmp-pendulum span{animation:pnd 2.8s ease-in-out infinite;animation-delay:calc(var(--i)*-58ms)}
@keyframes pnd{0%,100%{opacity:.4}25%{opacity:1;filter:brightness(1.7)}50%{opacity:.4}75%{opacity:1;filter:brightness(1.7)}}
.rmp-wipe span{animation:wip 1.9s steps(1,end) infinite;animation-delay:calc(var(--i)*52ms - 11400ms)}
@keyframes wip{0%,49%{opacity:.38}50%,100%{opacity:1}}
.rmp-pop span{animation:pop 2.4s ease-out infinite}
@keyframes pop{0%{opacity:.3}4%{opacity:1;filter:brightness(2.2)}18%,100%{opacity:1;filter:none}}
.rmp-converge span{animation:cvg 2.4s ease-in-out infinite;animation-delay:calc(abs(var(--i) - 13)*-62ms)}
@keyframes cvg{0%,55%{opacity:.4}72%{opacity:1;filter:brightness(1.6)}100%{opacity:.4}}
.rmp-g-lin span{opacity:calc(.45 + var(--i)*.022)}
.rmp-g-map span{filter:hue-rotate(calc(var(--i)*7deg)) brightness(calc(.8 + var(--i)*.014))}
.rmp-g-step span{opacity:calc(.4 + (round(down, var(--i)/6) * .14))}
.rmp-g-pal span{filter:hue-rotate(calc(mod(var(--i),5)*62deg))}
.rmp-g-cent span{opacity:calc(1 - abs(var(--i) - 14)*.035)}
.rmp-heartbeat span{animation:hb 1.2s steps(1,end) infinite}
@keyframes hb{0%,8%{opacity:1}9%,18%{opacity:.35}19%,27%{opacity:1}28%,100%{opacity:.35}}
.rmp-type span{animation:typ 2.6s steps(1,end) infinite;animation-delay:calc(var(--i)*70ms)}
@keyframes typ{0%{opacity:0}4%,100%{opacity:1}}
.rmp-marquee span{animation:mrq 2.6s linear infinite;animation-delay:calc(var(--i)*85ms - 15600ms)}
@keyframes mrq{0%,86%{opacity:.5}92%{opacity:1;filter:brightness(1.8)}98%,100%{opacity:.5}}
.rmp-ripple span{animation:rip 1.9s ease-out infinite;animation-delay:calc(abs(var(--i) - 12)*60ms)}
@keyframes rip{0%{opacity:.4}18%{opacity:1;filter:brightness(1.9)}55%,100%{opacity:.4}}
.rmp-chase span{animation:chs 1.1s linear infinite;animation-delay:calc(var(--i)*40ms - 6600ms)}
@keyframes chs{0%,78%{opacity:.4}84%{opacity:1}90%{opacity:.75}96%,100%{opacity:.4}}
.rmp-neon span{animation:non 3.1s steps(1,end) infinite;animation-delay:calc(var(--i)*23ms - 18600ms)}
@keyframes non{0%,3%{opacity:.3}4%,7%{opacity:1}8%,11%{opacity:.3}12%,60%{opacity:1}61%,63%{opacity:.4}64%,100%{opacity:1}}
.rmp-drift span{animation:drf 3.4s ease-in-out infinite;animation-delay:calc(var(--i)*95ms - 20400ms)}
@keyframes drf{0%,100%{opacity:.34;filter:none}45%{opacity:1;filter:brightness(1.55) saturate(1.3)}70%{opacity:.6}}
.rmp-bookend span{animation:bke 2.2s ease-in-out infinite;animation-delay:calc((14 - abs(var(--i) - 14))*55ms)}
@keyframes bke{0%,60%{opacity:.4}75%{opacity:1;filter:brightness(1.5)}100%{opacity:.4}}
.rmp-scatter span{animation:sct 2.4s steps(1,end) infinite;animation-delay:calc(mod(var(--i)*7,13)*180ms)}
@keyframes sct{0%,10%{opacity:1;filter:brightness(1.6)}11%,100%{opacity:.45}}
.rmp-sweep span{animation:swp 1.1s linear 1;animation-delay:calc(var(--i)*45ms - 6600ms)}
@keyframes swp{0%{opacity:.3}40%{opacity:1;filter:brightness(1.8)}100%{opacity:1}}


.rule-badge{float:right;color:#777;font:10px/1.3 ui-monospace,monospace;letter-spacing:0;text-transform:none}
.rule-badge a{color:inherit;text-decoration:none}.rule-badge a:hover{text-decoration:underline}
.generated-count,.rule-ref{color:inherit}.registry-note{border-left:2px solid #333;padding-left:10px}
.registry-history summary{cursor:pointer;color:#aaa}.registry-history{margin-top:12px}
.build-status{color:#8a8a8a;font-size:11px;margin:-6px 0 16px}

